const test=require('node:test');const assert=require('node:assert/strict');const S=require('./sampling.js');
test('CDF endpoints never choose a zero-mass cell',()=>{assert.equal(S.categorical([0,.2,0,.8],0),1);assert.equal(S.categorical([0,.2,0,.8],.2),3);assert.equal(S.categorical([0,0],.5),null);assert.throws(()=>S.categorical([1],1));assert.throws(()=>S.normalize([NaN]));});
test('seeded IID draws are reproducible and masks renormalize',()=>{const args={weights:[.1,.2,.3,.4],mask:[false,false,true,true],count:5,seed:919};const a=S.sampleSet(args),b=S.sampleSet(args);assert.deepEqual(a,b);assert.ok(a.draws.every(d=>d.cell>=2));assert.ok(Math.abs(a.retainedMass-.7)<1e-12);assert.ok(Math.abs(a.shown[2]-3/7)<1e-12);for(const d of a.draws)assert.equal(d.conditionalQ,a.eligible[d.cell]);});
test('IID duplicates remain explicit; no diversity rejection',()=>{const x=S.sampleSet({weights:[0,1],count:5,seed:4});assert.deepEqual(x.draws.map(d=>d.cell),[1,1,1,1,1]);assert.deepEqual(x.uniqueCells,[1]);});
test('event coverage uses five different conditional laws and preserves abstentions',()=>{const x=S.sampleSet({weights:[1,2,0,4,5],count:5,seed:4,scheme:'events',groups:[0,1,2,3,4]});assert.deepEqual(x.draws.map(d=>d.cell),[0,1,null,3,4]);assert.equal(x.abstentions,1);assert.ok(Math.abs(x.shown.reduce((a,b)=>a+b,0)-.8)<1e-12);assert.ok(x.draws.filter(d=>d.cell!==null).every(d=>d.conditionalQ===1));});
test('zero-support whole set abstains',()=>{const x=S.sampleSet({weights:[0,0],count:3,seed:0});assert.equal(x.abstentions,3);assert.deepEqual(x.uniqueCells,[]);});
test('empirical seeded categorical frequencies match a known law',()=>{const w=[.01,.09,.2,.3,.4],n=100000,counts=w.map(()=>0),r=S.rng(8182);for(let k=0;k<n;k++)counts[S.categorical(w,r())]++;assert.ok(counts.every((v,i)=>Math.abs(v/n-w[i])<.005),JSON.stringify(counts));});

test('primitive set overlap respects yaw, vertical separation and spheres',()=>{assert.equal(S.overlaps([0,0,0,0,0],[.4,0,0,0,0]),false);assert.equal(S.overlaps([0,0,0,0,Math.PI/2],[.4,0,0,0,Math.PI/2]),true);assert.equal(S.overlaps([0,0,0,1,0],[0,0,2,1,0]),false);assert.equal(S.overlaps([0,0,0,2,0],[.59,0,0,2,0]),true);assert.equal(S.overlaps([0,0,0,2,0],[.61,0,0,2,0]),false);assert.equal(S.overlaps([0,0,0,1,0],[.4,0,0,2,0]),true);});

test('sequential overlap filtering renormalizes and never retries failed slots',()=>{const x=S.sampleSet({weights:[.5,.5],count:3,seed:17,avoidOverlap:true,specs:[[0,0,0,1,0],[2,0,0,1,0]]});assert.equal(x.draws[0].conditionalQ,.5);assert.equal(x.draws[1].conditionalQ,1);assert.notEqual(x.draws[0].cell,x.draws[1].cell);assert.equal(x.draws[2].cell,null);assert.equal(x.abstentions,1);assert.deepEqual(x.draws[2].q,[0,0]);});
